\begin{aligned}f(n+1) &= e\left[ 1 - \frac{1}{2n} + \frac{1}{2n^2} - \frac{1}{2n^3} + \frac{11}{24n^2} - \frac{11}{12n^3} + O\left(\frac{1}{n^3}\right) \right] \\ &= e\left[ 1 - \frac{1}{2n} + \left(\frac{1}{2}+\frac{11}{24}\right)\frac{1}{n^2} + \left(-\frac{1}{2} - \frac{11}{12}\right)\frac{1}{n^3} + O\left(\frac{1}{n^3}\right) \right] \\
 &= e\left[ 1 - \frac{1}{2n} + \frac{23}{24n^2} - \frac{17}{12n^3} + O\left(\frac{1}{n^3}\right) \right].
\end{aligned}

\begin{aligned}f(n+1) - f(n) &= e\left[ \left(1 - \frac{1}{2n} + \frac{23}{24n^2} - \frac{17}{12n^3}\right) - \left(1 - \frac{1}{2n} + \frac{11}{24n^2}\right) + O\left(\frac{1}{n^3}\right) \right] \\&= e\left[ \left(\frac{23}{24} - \frac{11}{24}\right)\frac{1}{n^2} - \frac{17}{12n^3} + O\left(\frac{1}{n^3}\right) \right] \\&= e\left[ \frac{12}{24n^2} - \frac{17}{12n^3} + O\left(\frac{1}{n^3}\right) \right] \\
&= e\left[ \frac{1}{2n^2} - \frac{17}{12n^3} + O\left(\frac{1}{n^3}\right) \right].
\end{aligned}

\begin{aligned}L &= \lim_{n\to\infty} n^2 \left[ f(n+1) - f(n) \right] \\ &= \lim_{n\to\infty} n^2 \cdot e\left[ \frac{1}{2n^2} - \frac{17}{12n^3} + O\left(\frac{1}{n^3}\right) \right] \\ &= \lim_{n\to\infty} e\left[ \frac{1}{2} - \frac{17}{12n} + O\left(\frac{1}{n}\right) \right] \\
 &= e \cdot \frac{1}{2}.
\end{aligned}
